insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 17, 17, 'E fizeram passar a seus filhos e a suas filhas por fogo; e deram-se a adivinhações e agouros, e entregaram-se a fazer o que era mau aos olhos do SENHOR, provocando-o à ira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 17, 18, 'O SENHOR, portanto, se irou em grande maneira contra Israel, e tirou-os de diante de seu rosto; que não restou a não ser somente a tribo de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 17, 19, 'Mas nem ainda Judá guardou os mandamentos do SENHOR seu Deus; antes andaram nos estatutos de Israel, os quais eles haviam feito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 17, 20, 'E rejeitou o SENHOR toda a semente de Israel, e afligiu-os, e entregou-os em mãos de saqueadores, até lançá-los de sua presença.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 17, 21, 'Porque cortou a Israel da casa de Davi, e eles se fizeram rei a Jeroboão filho de Nebate; e Jeroboão desviou a Israel de seguir o SENHOR, e fez-lhes cometer grande pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 17, 22, 'E os filhos de Israel andaram em todos os pecados de Jeroboão que ele fez, sem desviar-se deles;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 17, 23, 'Até que o SENHOR tirou a Israel de diante de seu rosto, como o havia ele dito por meio de todos os profetas seus servos: e Israel foi transportado de sua terra à Assíria, até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 17, 24, 'E trouxe o rei da Assíria gente de Babilônia, e de Cuta, e de Hava, e de Hamate, e de Sefarvaim, e os pôs nas cidades de Samaria, em lugar dos filhos de Israel; e possuíram a Samaria, e habitaram em suas cidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 17, 25, 'E aconteceu ao princípio, quando começaram a habitar ali, que não temendo eles ao SENHOR, enviou o SENHOR contra eles leões que os matavam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 17, 26, 'Então disseram eles ao rei da Assíria: As nações que tu transportaste e puseste nas cidades de Samaria, não sabem a costume do Deus daquela terra, e ele lançou leões neles, e eis que os matam, porque não sabem a costume do Deus da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 17, 27, 'E o rei da Assíria mandou, dizendo: Levai ali a algum dos sacerdotes que trouxestes dali, e vão e habitem ali, e ensinem-lhes o costume do Deus daquela terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 17, 28, 'E veio um dos sacerdotes que haviam transportado de Samaria, e habitou em Betel, e ensinou-lhes como haviam de temer ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 17, 29, 'Mas cada nação fez para si seus deuses, e puseram-nos nos templos dos altos que haviam feito os de Samaria; cada nação em sua cidade onde habitava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 17, 30, 'Os da Babilônia fizeram a Sucote-Benote, e os de Cuta fizeram a Nergal, e os de Hamate fizeram a Asima;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 17, 31, 'Os heveus fizeram a Nibaz e a Tartaque; e os de Sefarvaim queimavam seus filhos ao fogo a Adrameleque e a Anameleque, deuses de Sefarvaim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 17, 32, 'E temiam ao SENHOR; e fizeram dos do povo sacerdotes dos altos, os quais sacrificavam para eles nos templos dos altos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 17, 33, 'Temiam ao SENHOR, e honravam a seus deuses, segundo o costume das nações de onde haviam sido transportados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 17, 34, 'Até hoje fazem como primeiro; que nem temem ao SENHOR, nem guardam seus estatutos, nem suas ordenanças, nem fazem segundo a lei e os mandamentos que prescreveu o SENHOR aos filhos de Jacó, ao qual pôs o nome de Israel;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 17, 35, 'Com os quais havia o SENHOR feito pacto, e lhes mandou, dizendo: Não temereis a outros deuses, nem os adorareis, nem lhes servireis, nem lhes sacrificareis:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 17, 36, 'Mas ao SENHOR, que vos tirou da terra do Egito com grande poder e braço estendido, a este temereis, e a este adorareis, e a este fareis sacrifício.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 17, 37, 'Os estatutos e direitos e lei e mandamentos que vos deu por escrito, cuidareis sempre de praticá-los, e não temereis deuses alheios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 17, 38, 'E não esquecereis o pacto que fiz convosco; nem temereis deuses alheios:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 17, 39, 'Mas temei ao SENHOR vosso Deus, e ele vos livrará da mão de todos vossos inimigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 17, 40, 'Porém eles não escutaram; antes fizeram segundo seu costume antigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 17, 41, 'Assim temeram ao SENHOR aquelas nações, e juntamente serviram a seus ídolos: e também seus filhos e seus netos, segundo que fizeram seus pais, assim fazem até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 18, 1, 'No terceiro ano de Oseias filho de Elá rei de Israel, começou a reinar Ezequias filho de Acaz rei de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 18, 2, 'Quando começou a reinar era de vinte e cinco anos, e reinou em Jerusalém vinte e nove anos. O nome de sua mãe foi Abi filha de Zacarias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 18, 3, 'Fez o que era correto aos olhos do SENHOR, conforme todas as coisas que havia feito Davi seu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 18, 4, 'Ele tirou os altos, e quebrou as imagens, e arrancou os bosques, e fez pedaços a serpente de bronze que havia feito Moisés, porque até então lhe queimavam incenso os filhos de Israel; e chamou-lhe por nome Neustã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 18, 5, 'No SENHOR Deus de Israel pôs sua esperança: depois nem antes dele não houve outro como ele em todos os reis de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 18, 6, 'Porque se chegou ao SENHOR, e não se separou dele, mas sim que guardou os mandamentos que o SENHOR prescreveu a Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 18, 7, 'E o SENHOR foi com ele; e em todas as coisas a que saía prosperava. Ele se rebelou contra o rei da Assíria, e não lhe serviu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 18, 8, 'Feriu também aos filisteus até Gaza e seus termos, desde as torres das atalaias até a cidade fortificada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 18, 9, 'No quarto ano do rei Ezequias, que era o ano sétimo de Oseias filho de Elá rei de Israel, subiu Salmaneser rei dos assírios contra Samaria, e cercou-a.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 18, 10, 'E tomaram-na ao fim de três anos: isto é, no sexto ano de Ezequias, o qual era o ano nono de Oseias rei de Israel, foi Samaria tomado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 18, 11, 'E o rei da Assíria transportou a Israel à Assíria, e os pôs em Hala, e em Habor, junto ao rio de Gozã, e nas cidades dos medos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 18, 12, 'Porquanto não haviam atendido à voz do SENHOR seu Deus, antes haviam quebrado o seu pacto; e todas as coisas que Moisés servo do SENHOR havia mandado, nem as haviam escutado, nem praticado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 18, 13, 'E aos catorze anos do rei Ezequias, subiu Senaqueribe rei da Assíria contra todas as cidades fortes de Judá, e tomou-as.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 18, 14, 'Então Ezequias, rei de Judá, mandou dizer ao rei da Assíria em Laquis: Eu pequei; afasta-te de mim, e suportarei tudo o que me impuseres. E o rei da Assíria impôs a Ezequias rei de Judá trezentos talentos de prata, e trinta talentos de ouro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 18, 15, 'Deu, portanto, Ezequias toda a prata que foi achada na casa do SENHOR, e nos tesouros da casa real.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 18, 16, 'Então desmontou Ezequias as portas do templo do SENHOR, e as dobradiças que o mesmo rei Ezequias havia coberto de ouro, e deu-o ao rei da Assíria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 18, 17, 'Depois o rei da Assíria enviou ao rei Ezequias, desde Laquis contra Jerusalém, a Tartã e a Rabe-Saris e a Rabsaqué, com um grande exército: e subiram, e vieram a Jerusalém. E havendo subido, vieram e pararam junto ao aqueduto do tanque de acima,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 18, 18, 'Chamaram logo ao rei, e saiu a eles Eliaquim filho de Hilquias, que era mordomo, e Sebna escriba, e Joá filho de Asafe, chanceler.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 18, 19, 'E disse-lhes Rabsaqué: Dizei agora a Ezequias: Assim diz o grande rei da Assíria: Que confiança é esta em que tu estás?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 18, 20, 'Dizes, (por certo palavras de lábios): Tenho conselho e esforço para a guerra. Mas em que confias, que te rebelaste contra mim?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 18, 21, 'Eis que tu confias agora neste bordão de cana quebrada, em Egito, no que se alguém se apoiar, lhe entrará pela mão, e se lhe passará. Assim é Faraó, rei do Egito, para todos os que nele confiam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 18, 22, 'E se me dizeis: Nós confiamos no SENHOR nosso Deus: não é aquele cujos altos e altares tirou Ezequias, e disse a Judá e a Jerusalém: Diante deste altar adorareis em Jerusalém?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 18, 23, 'Portanto, agora eu te rogo que dês reféns a meu senhor, o rei da Assíria, e eu te darei dois mil cavalos, se tu puderes dar cavaleiros para eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 18, 24, 'Como, pois, farás virar o rosto de um capitão o menor dos servos de meu senhor, ainda que estais confiantes no Egito por seus carros e seus cavaleiros?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 18, 25, 'Além disso, acaso eu vim sem o SENHOR a este lugar, para destruí-lo? Foi o SENHOR que me disse: Sobe a esta terra, e destrói-a.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 18, 26, 'Então disse Eliaquim filho de Hilquias, e Sebna e Joá, a Rabsaqué: Rogo-te que fales a teus servos em siríaco, porque nós o entendemos, e não fales conosco judaico a ouvidos do povo que está sobre o muro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 18, 27, 'E Rabsaqué lhes disse: Enviou-me meu senhor a ti e a teu senhor para dizer estas palavras, e não antes aos homens que estão sobre o muro, para comerem o seu excremento, e beberem a sua própria urina convosco?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 18, 28, 'Logo Rabsaqué ficou de pé, e clamou em alta voz na língua judaica, e falou, dizendo: Ouvi a palavra do grande rei, o rei da Assíria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 18, 29, 'Assim disse o rei: Não vos engane Ezequias, porque não vos poderá livrar de minha mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 18, 30, 'E não vos faça Ezequias confiar no SENHOR, dizendo: De certo nos livrará o SENHOR, e esta cidade não será entregue em mão do rei da Assíria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 18, 31, 'Não ouçais a Ezequias, porque assim diz o rei da Assíria: Fazei comigo paz, e saí a mim, e cada um comerá de sua vide, e de sua figueira, e cada um beberá as águas de seu poço;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 18, 32, 'Até que eu venha, e vos leve a uma terra como a vossa, terra de grão e de vinho, terra de pão e de vinhas, terra de olivas, de azeite, e de mel; e vivereis, e não morrereis. Não ouçais a Ezequias, porque vos engana quando disse: o SENHOR nos livrará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 18, 33, 'Acaso algum dos deuses das nações livrou sua terra da mão do rei da Assíria?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 18, 34, 'Onde está o deus de Hamate, e de Arpade? Onde está o deus de Sefarvaim, de Hena, e de Iva? Puderam estes livrar a Samaria de minha mão?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 18, 35, 'Que deus de todos os deuses das províncias livrou a sua província de minha mão, para que livre o SENHOR de minha mão a Jerusalém?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 18, 36, 'E o povo se calou, de maneira que não lhe responderam palavra: porque havia mandamento do rei, o qual havia dito: Não lhe respondais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 18, 37, 'Então Eliaquim filho de Hilquias, que era mordomo, e Sebna o escriba, e Joá filho de Asafe, chanceler, vieram a Ezequias, com suas roupas rasgadas, e contaram-lhe as palavras de Rabsaqué.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 19, 1, 'E quando o rei Ezequias o ouviu, rasgou suas roupas, e cobriu-se de saco, e entrou-se na casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 19, 2, 'E enviou a Eliaquim o mordomo, e a Sebna escriba, e aos anciãos dos sacerdotes, vestidos de sacos a Isaías profeta filho de Amoz,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 19, 3, 'Que lhe dissessem: Assim disse Ezequias: Este dia é dia de angústia, e de repreensão, e de blasfêmia; porque os filhos vieram até o ponto do parto, mas a que dá à luz não tem forças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 19, 4, 'Talvez ouvirá o SENHOR tua Deus todas as palavras de Rabsaqué, ao qual o rei dos assírios, seu senhor, enviou para afrontar o Deus vivo, e repreenderá pelas palavras que o SENHOR teu Deus ouviu: portanto, eleva oração pelos restantes que ainda continuam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 19, 5, 'Vieram, pois, os servos do rei Ezequias a Isaías.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 19, 6, 'E Isaías lhes respondeu: Assim direis a vosso senhor: Assim disse o SENHOR; Não temas pelas palavras que ouviste, com as quais me blasfemaram os servos do rei da Assíria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 19, 7, 'Eis que porei eu nele um espírito, e ouvirá rumor, e se voltará à sua terra: e eu farei que em sua terra caia à espada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 19, 8, 'E regressando Rabsaqué, achou ao rei da Assíria combatendo a Libna; porque havia ouvido que se havia partido de Laquis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 19, 9, 'E ouviu dizer de Tiraca rei de Etiópia: Eis que saiu para fazer-te guerra. Então voltou ele, e enviou embaixadores a Ezequias, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 19, 10, 'Assim direis a Ezequias rei de Judá: Não te engane teu Deus em quem tu confias, para dizer: Jerusalém não será entregue em mão do rei da Assíria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 19, 11, 'Eis que tu ouviste o que fizeram os reis da Assíria a todas as terras, destruindo-as; e hás tu de escapar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 19, 12, 'Livraram-nas os deuses das nações, que meus pais destruíram, a saber, Gozã, e Harã, e Rezefe, e os filhos de Éden que estavam em Telassar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 19, 13, 'Onde está o rei de Hamate, o rei de Arpade, o rei da cidade de Sefarvaim, de Hena, e de Iva?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 19, 14, 'E tomou Ezequias as cartas da mão dos embaixadores; e depois que as leu, subiu à casa do SENHOR, e estendeu-as Ezequias diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 19, 15, 'E orou Ezequias diante do SENHOR, dizendo: SENHOR Deus de Israel, que habitas entre os querubins, tu só és Deus de todos os reinos da terra; tu fizeste o céu e a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 19, 16, 'Inclina, ó SENHOR, teu ouvido, e ouve; abre, ó SENHOR, teus olhos, e olha: e ouve as palavras de Senaqueribe, que enviou a blasfemar ao Deus vivente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 19, 17, 'É verdade, ó SENHOR, que os reis da Assíria destruíram as nações e suas terras;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 19, 18, 'E que puseram no fogo a seus deuses, porquanto eles não eram deuses, mas sim obra de mãos de homens, madeira ou pedra, e assim os destruíram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 19, 19, 'Agora, pois, ó SENHOR Deus nosso, salva-nos, te suplico, de sua mão, para que saibam todos os reinos da terra que só tu, SENHOR, és Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 19, 20, 'Então Isaías filho de Amoz enviou a dizer a Ezequias: Assim disse o SENHOR, Deus de Israel: O que me rogaste acerca de Senaqueribe rei da Assíria, ouvi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 19, 21, 'Esta é a palavra que o SENHOR falou contra ele: Menosprezou-te, escarneceu-te a virgem filha de Sião; moveu sua cabeça detrás de ti a filha de Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 19, 22, 'A quem afrontaste e a quem blasfemaste? E contra quem falaste alto, e levantaste em alto teus olhos? Contra o Santo de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 19, 23, 'Por meio de teus mensageiros proferiste afronta contra o Senhor, e disseste: Com a multidão de meus carros subi aos cumes dos montes, às costas do Líbano; e cortarei seus altos cedros, suas faias escolhidas; e entrarei à morada de seu termo, à floresta de seu terreno fértil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 19, 24, 'Eu cavei e bebi as águas alheias, e sequei com as plantas de meus pés todos os rios de lugares bloqueados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 19, 25, 'Nunca ouviste que há muito tempo eu o fiz, e de dias antigos o formei? E agora o fiz vir, e foi para desolação de cidades fortes em amontoados de ruínas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 19, 26, 'E seus moradores, fracos de mãos, quebrantados e confusos, foram qual erva do campo, como hortaliça verde, e feno dos telhados, que antes que venha a maturidade é seco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 19, 27, 'Eu soube teu assentar-te, teu sair e teu entrar, e teu furor contra mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 19, 28, 'Porquanto te iraste contra mim, e teu estrondo subiu a meus ouvidos, eu, portanto, porei meu anzol em tuas narinas, e meu freio em teus lábios, e te farei voltar pelo caminho por onde vieste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 19, 29, 'E isto te será por sinal Ezequias: Este ano comerás o que nascerá de si mesmo, e no segundo ano o que nascerá de si mesmo; e ao terceiro ano semeareis, e colhereis, e plantareis vinhas, e comereis o fruto delas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 19, 30, 'E o que houver escapado, o que haverá restado da casa de Judá, voltará a lançar raiz abaixo, e dará fruto acima.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 19, 31, 'Porque sairão de Jerusalém remanescentes, e os que escaparão, do monte de Sião: o zelo do SENHOR dos exércitos fará isto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 19, 32, 'Portanto, o SENHOR diz assim do rei da Assíria: Não entrará nesta cidade, nem lançará flecha nela; nem virá diante dela escudo, nem será levantado baluarte contra ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 19, 33, 'Pelo caminho que veio se voltará, e não entrará nesta cidade, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 19, 34, 'Porque eu ampararei a esta cidade para salvá-la, por causa de mim, e por causa de Davi meu servo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 19, 35, 'E aconteceu que a mesma noite saiu o anjo do SENHOR, e feriu no campo dos assírios cento oitenta e cinco mil; e quando se levantaram pela manhã, eis que eram todos cadáveres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 19, 36, 'Então Senaqueribe, rei da Assíria, partiu-se, e se foi e voltou a Nínive, onde ficou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 19, 37, 'E aconteceu que, estando ele adorando no templo de Nisroque seu deus, Adrameleque e Sarezer seus filhos o feriram à espada; e fugiram-se à terra de Ararate. E reinou em seu lugar Esar-Hadom seu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 20, 1, 'Naqueles dias caiu Ezequias enfermo de morte, e veio a ele Isaías profeta filho de Amoz, e disse-lhe: o SENHOR disse assim: Dá ordens à tua casa, porque hás de morrer, e não viverás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 20, 2, 'Então virou ele seu rosto à parede, e orou ao SENHOR, e disse:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 20, 3, 'Rogo-te, ó SENHOR, rogo-te faças memória de que andei diante de ti em verdade e íntegro coração, e que fiz as coisas que te agradam. E chorou Ezequias com grande choro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 20, 4, 'E antes que Isaías saísse até a metade do pátio, veio a palavra do SENHOR a Isaías, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 20, 5, 'Volta, e dize a Ezequias, príncipe de meu povo: Assim diz o SENHOR, o Deus de Davi teu pai: Eu ouvi tua oração, e vi tuas lágrimas: eis que eu te saro; ao terceiro dia subirás à casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 20, 6, 'E acrescentarei a teus dias quinze anos, e te livrarei a ti e a esta cidade da mão do rei da Assíria; e ampararei esta cidade por causa de mim, e por causa de Davi meu servo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 20, 7, 'E disse Isaías: Tomai uma pasta de figos. E tomando-a, puseram sobre a chaga, e sanou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 20, 8, 'E Ezequias havia dito a Isaías: Que sinal terei de que o SENHOR me sarará, e que subirei à casa do SENHOR ao terceiro dia?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 20, 9, 'E respondeu Isaías: Esta sinal terás do SENHOR, de que fará o SENHOR isto que disse: Avançará a sombra dez degraus, ou retrocederá dez degraus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 20, 10, 'E Ezequias respondeu: Fácil coisa é que a sombra decline dez degraus: mas, que a sombra volte atrás dez degraus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 20, 11, 'Então o profeta Isaías clamou ao SENHOR; e fez voltar a sombra pelos degraus que havia descido no relógio de Acaz, dez degraus atrás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 20, 12, 'Naquele tempo Berodaque-Baladã, filho de Baladã, rei da Babilônia, enviou cartas e um presente a Ezequias, porque havia ouvido que Ezequias havia estado doente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 20, 13, 'E Ezequias os ouviu, e mostrou-lhes toda a casa das coisas preciosas, prata, ouro, e especiaria, e preciosos unguentos; e a casa de suas armas, e tudo o que havia em seus tesouros: nenhuma coisa restou que Ezequias não lhes mostrasse, tanto em sua casa como em todo o seu domínio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 20, 14, 'Então o profeta Isaías veio ao rei Ezequias, e disse-lhe: Que disseram aqueles homens, e de onde vieram a ti? E Ezequias lhe respondeu: De distantes terras vieram, de Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 20, 15, 'E ele lhe voltou a dizer: Que viram em tua casa? E Ezequias respondeu: Viram tudo o que havia em minha casa; nada restou em meus tesouros que não lhes mostrasse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 20, 16, 'Então Isaías disse a Ezequias: Ouve a palavra do SENHOR:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 20, 17, 'Eis que vêm dias, em que tudo o que está em tua casa, e tudo o que teus pais entesouraram até hoje, será levado a Babilônia, sem restar nada, disse o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 20, 18, 'E de teus filhos que sairão de ti, que haverás gerado, tomarão; e serão eunucos no palácio do rei da Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 20, 19, 'Então Ezequias disse a Isaías: A palavra do SENHOR que falaste, é boa. Depois disse: Mas não haverá paz e verdade em meus dias?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 20, 20, 'Os demais dos feitos de Ezequias, e todo o seu vigor, e como fez o tanque, e o aqueduto, e meteu as águas na cidade, não está escrito no livro das crônicas dos reis de Judá?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 20, 21, 'E descansou Ezequias com seus pais, e reinou em seu lugar Manassés seu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 21, 1, 'De doze anos era Manassés quando começou a reinar, e reinou em Jerusalém cinquenta e cinco anos: o nome de sua mãe foi Hefzibá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 21, 2, 'E fez o que era mau aos olhos do SENHOR, segundo as abominações das nações que o SENHOR havia lançado diante dos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 21, 3, 'Porque ele voltou a edificar os altos que Ezequias seu pai havia derrubado, e levantou altares a Baal, e fez bosque, como havia feito Acabe rei de Israel: e adorou a todo o exército do céu, e serviu àquelas coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 21, 4, 'Também edificou altares na casa do SENHOR, da qual o SENHOR havia dito: Eu porei meu nome em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 21, 5, 'E edificou altares para todo o exército do céu nos dois átrios da casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 21, 6, 'E passou a seu filho por fogo, e olhou em tempos, e foi agoureiro, e instituiu necromantes e adivinhos, multiplicando assim o fazer o mal aos olhos do SENHOR, para provocá-lo à ira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 21, 7, 'E pôs uma imagem entalhada do bosque que ele havia feito, na casa da qual havia o SENHOR dito a Davi e a Salomão seu filho: Eu porei meu nome para sempre nesta casa, e em Jerusalém, à qual escolhi de todas as tribos de Israel:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 21, 8, 'E não voltarei a fazer que o pé de Israel seja movido da terra que dei a seus pais, contanto que guardem e façam conforme a todas as coisas que eu lhes mandei, e conforme a toda a lei que meu servo Moisés lhes mandou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 21, 9, 'Mas eles não escutaram; e Manassés os induziu a que fizessem mais mal que as nações que o SENHOR destruiu diante dos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 21, 10, 'E falou o SENHOR por meio de seus servos os profetas, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 21, 11, 'Porquanto Manassés rei de Judá fez estas abominações, e fez mais mal que tudo o que fizeram os amorreus que foram antes dele, e também fez pecar a Judá em seus ídolos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 21, 12, 'Portanto, assim disse o SENHOR o Deus de Israel: Eis que eu trago tal mal sobre Jerusalém e sobre Judá, que o que o ouvir, lhe retinirão ambos ouvidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 21, 13, 'E estenderei sobre Jerusalém o cordel de Samaria, e o prumo da casa de Acabe: e eu limparei a Jerusalém como se limpa um prato, que depois que o limpam, viram-no sobre sua face.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 21, 14, 'E desampararei os restantes de minha propriedade, e os entregarei em mãos de seus inimigos; e serão para saque e para roubo a todos seus adversários;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 21, 15, 'Porquanto fizeram o mal aos meus olhos, e me provocaram à ira, desde o dia que seus pais saíram do Egito até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 21, 16, 'Além disso, derramou Manassés muito sangue inocente em grande maneira, até encher a Jerusalém de extremidade a extremidade; além de seu pecado com que fez pecar a Judá, para que fizesse o que era mau aos olhos do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 21, 17, 'Os demais dos feitos de Manassés, e todas as coisas que fez, e seu pecado que cometeu, não está tudo escrito no livro das crônicas dos reis de Judá?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 21, 18, 'E descansou Manassés com seus pais, e foi sepultado no jardim de sua casa, no jardim de Uzá; e reinou em seu lugar Amom seu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 21, 19, 'De vinte e dois anos era Amom quando começou a reinar, e reinou dois anos em Jerusalém. O nome de sua mãe foi Mesulemete filha de Haruz de Jotbá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 21, 20, 'E fez o que era mau aos olhos do SENHOR, como havia feito Manassés seu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 21, 21, 'E andou em todos os caminhos em que seu pai andou, e serviu às imundícias às quais havia servido seu pai, e a elas adorou;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 21, 22, 'E deixou ao SENHOR o Deus de seus pais, e não andou no caminho do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 21, 23, 'E os servos de Amom conspiraram contra ele, e mataram ao rei em sua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 21, 24, 'Então o povo da terra feriu a todos os que haviam conspirado contra o rei Amom; e pôs o povo da terra por rei em seu lugar a Josias seu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 21, 25, 'Os demais dos feitos de Amom, que efetuara, não está tudo escrito no livro das crônicas dos reis de Judá?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 21, 26, 'E foi sepultado em seu sepulcro no jardim de Uzá, e reinou em seu lugar Josias seu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 22, 1, 'Quando Josias começou a reinar era de oito anos, e reinou em Jerusalém trinta e um anos. O nome de sua mãe foi Jedida filha de Adaías de Bozcate.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 22, 2, 'E fez o que era correto aos olhos do SENHOR, e andou em todo o caminho de Davi seu pai, sem desviar-se à direita nem à esquerda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 22, 3, 'E aos dezoito anos do rei Josias, foi que enviou o rei a Safã filho de Azalias, filho de Mesulão, escriba, à casa do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 22, 4, 'Vai a Hilquias, sumo sacerdote: dize-lhe que recolha o dinheiro que se pôs na casa do SENHOR, que juntaram do povo os guardiões da porta,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 22, 5, 'E que o ponham em mãos dos que fazem a obra, que têm cargo da casa do SENHOR, e que o entreguem aos que fazem a obra da casa do SENHOR, para reparar as fendas da casa:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 22, 6, 'Aos carpinteiros, aos mestres e pedreiros, para comprar madeira e pedra lavrada para reparar a casa;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 22, 7, 'E que não se lhes conte o dinheiro cujo manejo se lhes confiar, porque eles procedem com fidelidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 22, 8, 'Então disse o sumo sacerdote Hilquias a Safã escriba: Achei o livro da lei na casa do SENHOR. E Hilquias deu o livro a Safã, e leu-o.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 22, 9, 'Vindo logo Safã escriba ao rei, deu ao rei a resposta, e disse: Teus servos juntaram o dinheiro que se achou no templo, e o entregaram em poder dos que fazem a obra, que têm cargo da casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 22, 10, 'Também Safã escriba declarou ao rei, dizendo: Hilquias o sacerdote me deu um livro. E leu-o Safã diante do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 22, 11, 'E quando o rei ouviu as palavras do livro da lei, rasgou suas roupas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 22, 12, 'Logo mandou o rei a Hilquias o sacerdote, e a Aicã filho de Safã, e a Acbor filho de Micaías, e a Safã escriba, e a Asaías servo do rei, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 22, 13, 'Ide, e perguntai ao SENHOR por mim, e pelo povo, e por todo Judá, acerca das palavras deste livro que se achou: porque grande ira do SENHOR é a que foi acesa contra nós, porquanto nossos pais não escutaram as palavras deste livro, para fazer conforme tudo o que nos foi escrito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 22, 14, 'Então foi Hilquias o sacerdote, e Aicã e Acbor e Safã e Asaías, a Hulda profetisa, mulher de Salum filho de Ticvá filho de Harás, guarda das vestiduras, a qual morava em Jerusalém na segunda parte da cidade, e falaram com ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 22, 15, 'E ela lhes disse: Assim disse o SENHOR o Deus de Israel: Dizei ao homem que vos enviou a mim:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 22, 16, 'Assim disse o SENHOR: Eis que eu trago mal sobre este lugar, e sobre os que nele moram, a saber, todas as palavras do livro que leu o rei de Judá:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 22, 17, 'Porquanto me deixaram, e queimaram incenso a deuses alheios, provocando-me à ira em toda obra de suas mãos; e meu furor se acendeu contra este lugar, e não se apagará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 22, 18, 'Mas ao rei de Judá que vos enviou para que perguntásseis ao SENHOR, direis assim: Assim disse o SENHOR o Deus de Israel: Porquanto ouviste as palavras do livro,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 22, 19, 'E teu coração se enterneceu, e te humilhaste diante do SENHOR, quando ouviste o que eu pronunciei contra este lugar e contra seus moradores, que viriam a ser assolados e malditos, e rasgaste tuas vestes, e choraste em minha presença, também eu te ouvi, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 22, 20, 'Portanto, eis que eu te recolherei com teus pais, e tu serás recolhido a teu sepulcro em paz, e não verão teus olhos todo o mal que eu trago sobre este lugar. E eles deram ao rei a resposta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 23, 1, 'Então o rei enviou aviso, e juntaram a ele todos os anciãos de Judá e de Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 23, 2, 'E subiu o rei à casa do SENHOR com todos os homens de Judá, e com todos os moradores de Jerusalém, com os sacerdotes e profetas e com todo o povo, desde o menor até o maior; e leu, ouvindo-o eles, todas as palavras do livro do pacto que havia sido achado na casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 23, 3, 'E pondo-se o rei em pé junto à coluna, fez aliança diante do SENHOR, de que seguiriam o SENHOR, e guardariam seus mandamentos, e seus testemunhos, e seus estatutos, com todo o coração e com toda a alma, e que cumpririam as palavras da aliança que estavam escritas naquele livro. E todo o povo confirmou o pacto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 23, 4, 'Então mandou el rei ao sumo sacerdote Hilquias, e aos sacerdotes de segunda ordem, e aos guardiões da porta, que tirassem do templo do SENHOR todos os vasos que haviam sido feitos para Baal, e para o bosque, e para toda o exército do céu; e queimou-os fora de Jerusalém no campo de Cedrom, e fez levar as cinzas deles a Betel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 23, 5, 'E tirou aos sacerdotes pagãos, que haviam posto os reis de Judá para que queimassem incenso nos altos nas cidades de Judá, e nos arredores de Jerusalém; e também aos que queimavam incenso a Baal, ao sol e à lua, e às constelações, e a todo o exército do céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 23, 6, 'Fez também tirar o bosque fora da casa do SENHOR, fora de Jerusalém, ao ribeiro de Cedrom, e queimou-o no ribeiro de Cedrom, e tornou-o em pó, e lançou o pó dele sobre os sepulcros dos filhos do povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 23, 7, 'Além disso derrubou as casas dos sodomitas que estavam na casa do SENHOR, nas quais teciam as mulheres tendas para o bosque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 23, 8, 'E fez vir todos os sacerdotes das cidades de Judá, e profanou os altos de onde os sacerdotes queimavam incenso, desde Gibeá até Berseba; e derrubou os altares das portas que estavam à entrada da porta de Josué, governador da cidade, que estavam à esquerda da porta da cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 23, 9, 'Porém os sacerdotes dos altos não subiam ao altar do SENHOR em Jerusalém, mas comiam pães sem levedura entre seus irmãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 23, 10, 'Também profanou a Tofete, que está no vale do filho de Hinom, porque ninguém passasse seu filho ou sua filha por fogo a Moloque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 23, 11, 'Tirou também os cavalos que os reis de Judá haviam dedicado ao sol à entrada do templo do SENHOR, junto à câmara de Natã-Meleque eunuco, a qual ficava nos recintos; e queimou ao fogo os carros do sol.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 23, 12, 'Derrubou também o rei os altares que estavam sobre o terraço da sala de Acaz, que os reis de Judá haviam feito, e os altares que havia feito Manassés nos dois átrios da casa do SENHOR; e dali correu e lançou o pó no ribeiro de Cedrom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 23, 13, 'Também profanou o rei os altos que estavam diante de Jerusalém, à direita do monte da destruição, os quais Salomão rei de Israel havia edificado a Astarote, abominação dos sidônios, e a Camos abominação de Moabe, e a Milcom abominação dos filhos de Amom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 23, 14, 'E quebrou as estátuas, e arrancou os bosques, e encheu o lugar deles de ossos de homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 23, 15, 'Igualmente o altar que estava em Betel, e o alto que havia feito Jeroboão filho de Nebate, o que fez pecar a Israel, aquele altar e o alto destruiu; e queimou o alto, e o tornou em pó, e pôs fogo ao bosque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 23, 16, 'E voltou-se Josias, e vendo os sepulcros que estavam ali no monte, enviou e tirou os ossos dos sepulcros, e queimou-os sobre o altar para contaminá-lo, conforme à palavra do SENHOR que havia profetizado o homem de Deus, o qual havia anunciado estes negócios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 23, 17, 'E depois disse: Que monumento é este que vejo? E os da cidade lhe responderam: Este é o sepulcro do homem de Deus que veio de Judá, e profetizou estas coisas que tu fizeste sobre o altar de Betel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 23, 18, 'E ele disse: Deixai-o; ninguém mova seus ossos: e assim foram preservados seus ossos, e os ossos do profeta que havia vindo de Samaria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 23, 19, 'E todas as casas dos altos que estavam nas cidades de Samaria, as quais haviam feito os reis de Israel para provocar a ira, tirou-as também Josias, e fez delas como havia feito em Betel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 23, 20, 'Também matou sobre os altares a todos os sacerdotes dos altos que ali estavam, e queimou sobre eles ossos de homens, e voltou-se a Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 23, 21, 'Então mandou o rei a todo o povo, dizendo: Fazei a páscoa ao SENHOR vosso Deus, conforme o que está escrito no livro desta aliança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 23, 22, 'Não foi feita tal páscoa desde os tempos dos juízes que governaram a Israel, nem em todos os tempos dos reis de Israel, e dos reis de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 23, 23, 'Aos dezoito anos do rei Josias foi feita aquela páscoa ao SENHOR em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 23, 24, 'Também expulsou Josias os necromantes, adivinhos, e ídolos, e todas as abominações que se viam na terra de Judá e em Jerusalém, para cumprir as palavras da lei que estavam escritas no livro que o sacerdote Hilquias havia achado na casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 23, 25, 'Não houve tal rei antes dele que se convertesse ao SENHOR de todo seu coração, e de toda sua alma, e de todas suas forças, conforme a toda a lei de Moisés; nem depois dele nasceu outro tal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 23, 26, 'Contudo isso, o SENHOR não se desviou do ardor de sua grande ira, com que se havia encendido sua ira contra Judá, por todas as provocações com que Manassés lhe havia irritado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 23, 27, 'E disse o SENHOR: Também tirarei de minha presença a Judá, como tirei a Israel, e abominarei a esta cidade que havia escolhido, a Jerusalém, e à casa da qual havia eu dito: Meu nome será ali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 23, 28, 'Os demais dos feitos de Josias, e todas as coisas que fez, não está tudo escrito no livro das crônicas dos reis de Judá?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 23, 29, 'Em aqueles dias Faraó Neco rei do Egito subiu contra o rei da Assíria ao rio Eufrates, e saiu contra ele o rei Josias; mas aquele assim que lhe viu, o matou em Megido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 23, 30, 'E seus servos o puseram em um carro, e trouxeram-no morto de Megido a Jerusalém, e sepultaram-no em seu sepulcro. Então o povo da terra tomou a Jeoacaz filho de Josias, e ungiram-lhe e puseram-no por rei em lugar de seu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 23, 31, 'De vinte e três anos era Jeoacaz quando começou a reinar, e reinou três meses em Jerusalém. O nome de sua mãe foi Hamutal, filha de Jeremias de Libna.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 23, 32, 'E ele fez o que era mau aos olhos do SENHOR, conforme todas as coisas que seus pais haviam feito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 23, 33, 'E lançou-o preso Faraó Neco em Ribla na província de Hamate, para que ele não reinasse em Jerusalém; e impôs sobre a terra uma multa de cem talentos de prata, e um de ouro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 23, 34, 'Então Faraó Neco pôs por rei a Eliaquim filho de Josias, em lugar de Josias seu pai, e mudou-lhe o nome no de Jeoaquim; e tomou a Jeoacaz, e levou-o ao Egito, e morreu ali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 23, 35, 'E Jeoaquim pagou a Faraó a prata e o ouro; mas fez tributar a terra para dar o dinheiro conforme ao mandamento de Faraó, tirando a prata e ouro do povo da terra, de cada um segundo a avaliação de sua riqueza, para dar a Faraó Neco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 23, 36, 'De vinte e cinco anos era Jeoaquim quando começou a reinar, e onze anos reinou em Jerusalém. O nome de sua mãe foi Zebida filha de Pedaías, de Ruma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 23, 37, 'E fez o que era mau aos olhos do SENHOR, conforme todas as coisas que seus pais haviam feito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 24, 1, 'Em seu tempo subiu Nabucodonosor, rei de Babilônia, ao qual Jeoaquim serviu por três anos; depois voltou-se contra e se rebelou contra ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 24, 2, 'O SENHOR, porém, enviou contra ele tropas de caldeus, e tropas de sírios, e tropas de moabitas, e tropas de amonitas; os quais enviou contra Judá para que a destruíssem, conforme a palavra do SENHOR que havia falado por meio dos seus servos, os profetas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 24, 3, 'Certamente foi por ordem do SENHOR que veio isto contra Judá, para tirá-la de sua presença, pelos pecados de Manassés, conforme tudo o que ele fez;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 24, 4, 'Também pelo sangue inocente que derramou, pois encheu Jerusalém de sangue inocente; o SENHOR, portanto, não quis perdoar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 24, 5, 'Os demais dos feitos de Jeoaquim, e todas as coisas que fez, não estão escritos no livro das crônicas dos reis de Judá?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 24, 6, 'E descansou Jeoaquim com seus pais, e reinou em seu lugar seu filho Joaquim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 24, 7, 'E nunca mais o rei do Egito saiu de sua terra; porque o rei da Babilônia lhe tomou tudo o que era seu, desde o rio do Egito até o rio de Eufrates.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 24, 8, 'Tinha Joaquim dezoito anos quando começou a reinar, e reinou em Jerusalém três meses. O nome de sua mãe foi Neusta filha de Elnatã, de Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 24, 9, 'E fez o que era mau aos olhos do SENHOR, conforme todas as coisas que seu pai havia feito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 24, 10, 'Naquele tempo subiram os servos de Nabucodonosor rei da Babilônia contra Jerusalém e a cidade foi cercada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 24, 11, 'Veio também Nabucodonosor rei da Babilônia contra a cidade, quando seus servos a tinham cercado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 24, 12, 'Então saiu Joaquim rei de Judá, para render-se ao rei da Babilônia, ele, e sua mãe, e seus servos, e seus príncipes, e seus eunucos; e o rei da Babilônia o prendeu no oitavo ano de seu reinado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 24, 13, 'E tirou dali todos os tesouros da casa do SENHOR, e os tesouros da casa real, e despedaçou todos os utensílios de ouro que havia feito Salomão rei de Israel na casa do SENHOR, como o SENHOR havia dito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 24, 14, 'E levou em cativeiro toda Jerusalém, todos os príncipes, e todos os homens valentes, até dez mil cativos, e todos os artesãos e ferreiros; que não restou ninguém, exceto os pobres do povo da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 24, 15, 'Também levou cativo Joaquim à Babilônia, assim como a mãe do rei, as mulheres do rei, os seus eunucos, e os poderosos daquela terra; cativos os levou de Jerusalém à Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 24, 16, 'A todos os homens de guerra, que foram sete mil, e aos oficiais e ferreiros, que foram mil, e a todos os valentes para fazer a guerra, levou cativos o rei da Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 24, 17, 'E o rei da Babilônia pôs como rei em lugar de Joaquim a Matanias, tio dele, e mudou-lhe o nome para Zedequias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 24, 18, 'De vinte e um anos era Zedequias quando começou a reinar, e reinou em Jerusalém onze anos. O nome de sua mãe foi Hamutal filha de Jeremias, de Libna.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 24, 19, 'E fez o que era mau aos olhos do SENHOR, conforme a tudo o que havia feito Jeoaquim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 24, 20, 'Assim aconteceu por causa da ira do SENHOR contra Jerusalém e Judá, até que os expulsou de sua presença. E Zedequias se rebelou contra o rei da Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 25, 1, 'E aconteceu aos nove anos de seu reinado, no mês décimo, aos dez do mês, que Nabucodonosor rei da Babilônia veio com todo seu exército contra Jerusalém, e cercou-a; e levantaram contra ela rampas de cerco ao redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 25, 2, 'E esteve a cidade cercado até o décimo primeiro ano do rei Zedequias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 25, 3, 'Aos nove do mês prevaleceu a fome na cidade, que não houve pão para o povo da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 25, 4, 'Aberta já a cidade, fugiram de noite todos os homens de guerra pelo caminho da porta que estava entre os dois muros, junto aos jardins do rei, estando os caldeus ao redor da cidade; e o rei se foi caminho da campina.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 25, 5, 'E o exército dos caldeus seguiu o rei, e tomou-o nas planícies de Jericó, e todo o seu exército se dispersou dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 25, 6, 'Tomado, pois, o rei, trouxeram-no ao rei da Babilônia a Ribla, e proferiram contra ele sentença.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 25, 7, 'E degolaram aos filhos de Zedequias em sua presença; e a Zedequias tiraram os olhos, e acorrentado com correntes levaram-no à Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 25, 8, 'No mês quinto, aos sete do mês, sendo o ano dezenove de Nabucodonosor rei da Babilônia, veio a Jerusalém Nebuzaradã, capitão dos da guarda, servo do rei da Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 25, 9, 'E queimou a casa do SENHOR, e a casa do rei, e todas as casas de Jerusalém; e todas as casas dos príncipes queimou a fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 25, 10, 'E todo o exército dos caldeus que estava com o capitão da guarda, derrubou os muros de Jerusalém ao redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 25, 11, 'E aos do povo que haviam restado na cidade, e aos que se haviam juntado ao rei da Babilônia, e aos que haviam restado da população, transportou-o Nebuzaradã, capitão dos da guarda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 25, 12, 'Mas dos pobres da terra deixou Nebuzaradã, capitão dos da guarda, para que lavrassem as vinhas e as terras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 25, 13, 'E quebraram os caldeus as colunas de bronze que estavam na casa do SENHOR, e as bases, e o mar de bronze que estava na casa do SENHOR, e levaram o bronze disso à Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 25, 14, 'Levaram-se também as caldeiras, e as pás, e as tenazes, e as colheres, e todos os vasos de bronze com que ministravam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 25, 15, 'Incensários, bacias, os que de ouro, em ouro, e os que de prata, em prata, tudo o levou o capitão dos da guarda;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 25, 16, 'As duas colunas, um mar, e as bases que Salomão havia feito para a casa do SENHOR: não havia peso de todos estes vasos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 25, 17, 'A altura da uma coluna era dezoito côvados e tinha encima um capitel de bronze, e a altura do capitel era de três côvados; e sobre o capitel havia um enredado e romãs ao redor, todo de bronze: e semelhante obra havia na outra coluna com o enredado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 25, 18, 'Tomou então o capitão dos da guarda a Seraías o sacerdote principal, e a Sofonias o segundo sacerdote, e três guardas da porta;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 25, 19, 'E da cidade tomou um eunuco, o qual comandava os soldados, e cinco homens dos assistentes do rei, que se acharam na cidade; e ao principal escriba do exército, que fazia o registro da gente daquela terra; e sessenta homens do povo da terra,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 25, 20, 'Nebuzaradã, capitão da guarda, tomou-os e os levou a Ribla, ao rei da Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 25, 21, 'E o rei da Babilônia os feriu e matou em Ribla, em terra de Hamate. Assim foi transportado Judá de sobre sua terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 25, 22, 'E ao povo que Nabucodonosor rei da Babilônia deixou em terra de Judá, pôs por governador a Gedalias, filho de Aicã filho de Safã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 25, 23, 'E ouvindo todos os príncipes do exército, eles e sua gente, que o rei da Babilônia havia posto por governador a Gedalias, vieram-se a ele em Mispá, a saber, Ismael filho de Netanias, e Joanã filho de Careá, e Seraías filho de Tanumete netofatita, e Jazanias filho do maacatita, eles com os seus subordinados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 25, 24, 'Então Gedalias lhes fez juramento, a eles e aos seus subordinados, e disse-lhes: Não temais de ser servos dos caldeus; habitai na terra, e servi ao rei da Babilônia, e vos irá bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 25, 25, 'Mas no mês sétimo veio Ismael filho de Netanias, filho de Elisama, da família real, e com ele dez homens, e feriram a Gedalias, e morreu, assim como os judeus e os caldeus que estavam com ele em Mispá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 25, 26, 'E levantando-se todo o povo, desde o menor até o maior, com os capitães do exército, foram-se ao Egito por temor dos caldeus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 25, 27, 'E aconteceu aos trinta e sete anos do cativeiro de Joaquim rei de Judá, no décimo segundo mês, aos vinte e sete do mês, que Evil-Merodaque rei da Babilônia, no primeiro ano de seu reinado, concedeu favor a Joaquim rei de Judá, tirando-o da prisão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 25, 28, 'E falou-lhe bem, e pôs seu assento em posição de maior honra do que o assento dos reis que estavam com ele na Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 25, 29, 'E mudou-lhe as roupas de sua prisão, e comeu sempre diante dele todos os dias de sua vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 12, '2 Reis', '2Rs', 25, 30, 'E foi-lhe continuamente dada a sua subsistência diária da parte do rei, por todos os dias de sua vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 1, 'Adão, Sete, Enos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 2, 'Cainã, Maalalel, Jarede,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 3, 'Enoque, Matusalém, Lameque,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 4, 'Noé, Sem, Cam, e Jafé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 5, 'Os filhos de Jafé foram: Gômer, Magogue, Dadai, Javã, Tubal, Meseque, e Tiras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 6, 'Os filhos de Gômer: Asquenaz, Rifate, e Togarma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 7, 'Os filhos de Javã: Elisá, Társis, Quitim, e Dodanim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 8, 'Os filhos de Cam: Cuxe, Misraim, Pute, e Canaã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 9, 'Os filhos de Cuxe: Sebá, Havilá, Sabtá, Raamá, e Sabtecá. E os filhos de Raamá foram: Sebá e Dedã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 10, 'E Cuxe gerou a Ninrode: este começou a ser poderoso na terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 11, 'Misraim gerou aos ludeus, aos ananeus, aos leabeus, aos leabeus, aos naftueus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 12, 'Aos patrusitas, e aos casluítas (destes saíram os Filisteus), e os caftoreus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 13, 'E Canaã gerou a Sidom, seu primogênito; e a Hete;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 14, 'E aos jebuseus, aos amorreus, aos girgaseus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 15, 'Aos heveus, aos arqueus, ao sineus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 16, 'Aos arvadeus, aos zemareus, e aos hamateus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 17, 'Os filhos de Sem foram: Elão, Assur, Arfaxade, Lude, Arã, Uz, Hul, Geter, e Meseque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 18, 'Arfaxade gerou a Selá, e Selá gerou a Héber.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 19, 'E a Héber nasceram dois filhos: o nome do um foi Pelegue, pois em seus dias a terra foi dividida; e o nome de seu irmão foi Joctã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 20, 'E Joctã gerou a Almodá, Salefe, Hazarmavé, e Jerá,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 21, 'E a Adorão, Uzal, Dicla,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 22, 'Ebal, Abimael, Sebá,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 23, 'Ofir, Havilá, e a Jobabe: todos filhos de Joctã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 24, 'Sem, Arfaxade, Selá,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 25, 'Héber, Pelegue, Reú,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 26, 'Serugue, Naor, Terá,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 27, 'E Abrão, o qual é Abraão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 28, 'Os filhos de Abraão foram: Isaque e Ismael.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 29, 'E estas são suas gerações: o primogênito de Ismael foi Nebaiote; [depois] Quedar, Adbeel, Mibsão,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 30, 'Misma, Dumá, Massá, Hadade, Temá,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 31, 'Jetur, Nafis, e Quedemá. Estes foram os filhos de Ismael.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 32, 'Quanto aos filhos de Quetura, concubina de Abraão, esta deu à luz Zinrã, Jocsã, Medã, Midiã, Isbaque, e a Suá. Os filhos de Jobsã: Sebá e Dedã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 33, 'Os filhos de Midiã: Efá, Efer, Enoque, Abida, e Elda; todos estes foram filhos de Quetura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 34, 'E Abraão gerou a Isaque: e os filhos de Isaque foram Esaú e Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 35, 'Os filhos de Esaú: Elifaz, Reuel, Jeús, Jalão, e Corá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 36, 'Os filhos de Elifaz: Temã, Omar, Zefi, Gatã, Quenaz, Timna, e Amaleque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 37, 'Os filhos de Reuel: Naate, Zerá, Samá, e Mizá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 38, 'Os filhos de Seir: Lotã, Sobal, Zibeão, Ana, Disom, Eser, e Disã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 39, 'Os filhos de Lotã: Hori, e Homã: e Timna foi irmã de Lotã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 40, 'Os filhos de Sobal: Aliã, Manaate, Ebal, Sefi e Onã. Os filhos de Zibeão foram: Aiá, e Aná.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 41, 'Disom foi filho de Aná: e os filhos de Disom foram Hanrão, Esbã, Itrã e Querã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 42, 'Os filhos de Eser foram: Bilã, Zaavã, e Jaacã. Os filhos de Disã: Uz e Arã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 43, 'E estes são os reis que reinaram na terra de Edom, antes que reinasse [algum] rei sobre os filhos de Israel: Belá, filho de Beor; e o nome de sua cidade era Dinabá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 44, 'Belá morreu, e reinou em seu lugar Jobabe, filho de Zerá, de Bozra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 45, 'Jobabe morreu, e reinou em seu lugar Husão, da terra dos Temanitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 46, 'Husão morreu, e reinou em seu lugar Hadade, filho de Bedade, o qual feriu aos midianitas no campo de Moabe; e o nome de sua cidade era Avite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 47, 'Hadade morreu, e reinou em seu lugar Sanlá, de Masreca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 48, 'Sanlá morreu, e reinou em seu lugar Saul de Reobote, que está junto ao rio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 49, 'E Saul morreu, e reinou em seu lugar Baal-Hanã, filho de Acbor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 50, 'E Baal-Hanã morreu, e reinou em seu lugar Hadade, cuja cidade tinha por nome Paí; e o nome de sua mulher era Meetabel, filha de Matrede, a filha de Mezaabe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 51, 'Hadade morreu. E os príncipes em Edom foram: o príncipe Timna, o príncipe Aliá, o príncipe Jetete,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 52, 'O príncipe Oolibama, o príncipe Elá, o príncipe Pinom,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 53, 'O príncipe Quenaz, o príncipe Temã, o príncipe Mibzar,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 1, 54, 'O príncipe Magdiel, o príncipe Irã. Estes foram os príncipe de Edom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 1, 'Estes são os filhos de Israel: Rúben, Simeão, Levi, Judá, Issacar, Zebulom,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 2, 'Dã, José, Benjamim, Naftali, Gade, e Aser.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 3, 'Os filhos de Judá foram: Er, Onã, e Selá. [Estes] três lhe nasceram de Bete-Suá, Cananeia. E Er, primogênito, de Judá, foi mau diante do Senhor, que o matou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 4, 'E Tamar, sua nora, lhe deu à luz Perez e a Zerá. Todos os filhos de Judá foram cinco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 5, 'Os filhos de Perez: Hezrom e Hamul.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 6, 'E os filhos de Zerá: Zinri, Etã, Hemã, e Calcol, e Darda; cinco ao todo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 7, 'O filho de Carmi foi Acar, o perturbador de Israel, porque transgrediu naquilo que estava separado por maldiçãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 8, 'O filho de Etã foi Azarias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 9, 'Os filhos que nasceram a Hezrom foram: Jerameel, Rão, e Quelubai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 10, 'E Rão gerou a Aminadabe; e Aminadabe gerou a Naasom, príncipe dos filhos de Judá;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 11, 'E Naasom gerou a Salmom, e Salmom gerou a Boaz;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 12, 'E Boaz gerou a Obede, e Obede gerou a Jessé;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 13, 'E Jessé gerou a Eliabe, seu primogênito, e o segundo Abinadabe, o terceiro Simeia;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 14, 'O quarto Natanael, o quinto Radai;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 15, 'O sexto Ozém, o sétimo Davi;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 16, 'As irmãs dos quais foram Zeruia e Abigail. Os filhos de Zeruia foram três: Abisai, Joabe, e Asael.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 17, 'E Abigail deu à luz Amasa, cujo pai foi Jéter, o Ismaelita.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 18, 'E Calebe filho de Hezrom gerou de sua mulher Azuba, e de Jeriote. E os filhos dela foram: Jeser, Sobabe, e Ardom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 19, 'E Azuba morreu, e Calebe tmou por mulher a Efrate, a qual lhe gerou a Hur.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 20, 'E Hur gerou a Uri, e Uri gerou a Bezalel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 21, 'Depois Hezrom se deitou com a filha de Maquir, pai de Gileade, a qual ele tomou por esposa quando ele tinha sessenta anos, e ela lhe gerou a Segube.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 22, 'E Segube gerou a Jair, que teve vinte e três cidades na terra de Gileade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 23, 'E Gesur e Arã tomaram deles as cidades de Jair, e a Quenate com suas aldeias, sessenta cidades. Todos estes foram filhos de Maquir, pai de Gileade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 24, 'E depois da morte de Hezrom, em Calebe de Efrata, Abia mulher de Hezrom, lhe gerou a Asur, pai de Tecoa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 25, 'E os filhos de Jerameel primogênito de Hezrom foram: Rão (seu primogênito), Buna, Orém, Ozém, e Aías.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 26, 'Jerameel também teve outra mulher chamada Atara, que foi mãe de Onã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 27, 'E os filhos de Rão, primogênito de Jerameel, foram: Maaz, Jamim, e Equer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 28, 'E os filhos de Onã foram: Samai, e Jada. E os filhos de Samai: Nadabe, e Abisur.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 29, 'E o nome da mulher de Abisur era Abiail, a qual lhe gerou a Abã e a Molide.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 30, 'E os filhos de Nadabe foram: Selede e Apaim. E Selede morreu sem filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 31, 'E o filho de Apaim foi Isi; o filho de Isi foi Sesã; e o filho de Sesã foi Alai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 32, 'E os filhos de Jada, irmão de Simmai, foram: Jéter e Jônatas. E Jéter morreu sem filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 33, 'E os filhos de Jônatas foram: Pelete, e Zaza. Estes foram os filhos de Jerameel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 34, 'E Sesã não teve filhos, mas somente filhas. E Sesã tinha um servo egípcio, cujo nome era Jará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 35, 'Sesã deu sua filha a seu servo Jará, e ela lhe gerou a Atai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 36, 'E Atai gerou a Natã, e Natã gerou a Zabade;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 37, 'E Zabade gerou a Eflal, e Eflal gerou a Obede;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 38, 'E Obede gerou a Jeú, e Jeú gerou a Azarias;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 39, 'E Azarias gerou a Helez, Helez gerou a Eleasá;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 40, 'Eleasá gerou a Sismai, e Sismai gerou a Salum;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 41, 'E Salum gerou a Jecamias, e Jecamias gerou a Elisama.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 42, 'Os filhos de Calebe, irmão de Jerameel, foram: Messa seu primogênito, que foi o pai de Zife; e os filhos de Maressa, pai de Hebrom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 43, 'E os filhos de Hebrom foram: Corá, Tapua, Requém, e Sema.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 44, 'E Sema gerou a Raão, pai de Jorqueão; e Requém gerou a Samai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 45, 'E o filho de Samai foi Maom, e Maom foi pai de Bete-Zur.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 46, 'E Efá, a concubina de Calebe, lhe gerou a Harã, Moza, e a Gazez. E Harã gerou a Gazez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 47, 'E os filhos de Jadai foram: Regém, Jotão, Gesã, Pelete, Efá, e Saafe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 48, 'Maaca, concubina de Calebe, lhe gerou a Seber, e a Tiraná.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 49, 'Ela também deu à luz a Saafe, pai de Madmana, e a Seva, pai de Macbena e pai de Gibeá. E a filha de Calebe foi Acsa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 50, 'Estes foram os filhos de Calebe, filho de Hur, primogênito de Efrata: Sobal, pai de Quiriate-Jearim;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 51, 'Salma, pai dos belemitas; e Harefe, pai de Bete-Gader.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 52, 'E os filhos de Sobal, pai de Quiriate-Jearim foram: Haroé, a metade dos Manaatitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 53, 'E as famílias de Quiriate-Jearim foram os itreus, os puteus, os sumateus, e os misraeus; destes saíram os zorateus e os estaoleus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 54, 'Os filhos de Salma foram: Belém, e os netofatitas, Atarote, Bete-Joabe; e da metade dos manaatitas, [e] os zoritas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 2, 55, 'E as famílias dos escribas, que habitavam em Jabez, foram os tiratitas, os simeatitas, [e] os sucatitas; estes foram os queneus que vieram de Hamate, pai da casa de Recabe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 3, 1, 'Estes são os filhos de Davi, que lhe nasceram em Hebrom: Amnom, o primogênito, de Ainoã Jezreelita; o segundo Daniel, de Abigail de Carmelo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 3, 2, 'O terceiro, Absalão, filho de Maaca, filha de Talmai, rei de Gesur; o quarto, Adonias, filho de Hagite;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 3, 3, 'O quinto, Sefatias, de Abital; o sexto, Itreão, de sua mulher Eglá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 3, 4, 'Estes seis lhe nasceram em Hebrom, de onde reinou sete anos e seis meses; e em Jerusalém reinou trinta e três anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 3, 5, 'Estes lhe nasceram em Jerusalém: Simeia, Sobabe, Natã, e Salomão, [estes] quatro de Bate-Sua, filha de Amiel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 3, 6, '[Nasceram-lhe] mais: Ibar, Elisama, Elifelete,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 3, 7, 'Nogá, Nefegue, Jafia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 3, 8, 'Elisama, Eliada, e Elifelete, nove.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 3, 9, 'Todos estes foram os filhos de Davi, exceto os filhos das concubinas. E Tamar foi irmã deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 3, 10, 'E o filho de Salomão foi Roboão, cujo filho foi Abias, cujo filho foi Asa, cujo filho foi Jeosafá;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 3, 11, 'Cujo filho foi Jorão, cujo filho foi Acazias, cujo filho foi Joás;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 3, 12, 'Cujo filho foi Amazias, cujo filho foi Azarias, cujo filho foi Jotão;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 3, 13, 'Cujo filho foi Acaz, cujo filho foi Ezequias, cujo filho foi Manassés;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 3, 14, 'Cujo filho foi Amom, cujo filho foi Josias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 3, 15, 'E os filhos de Josias foram: Joanã seu primogênito, o segundo Jeoaquim, o terceiro Zedequias, o quarto Salum.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 3, 16, 'Os filhos de Jeoaquim foram: seu filho Jeconias, e seu filho Zedequias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 3, 17, 'E os filhos de Jeconias, o cativo, foram: seu filho Sealtiel,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 3, 18, 'Malquirão, Pedaías, Senazar, Jecamias, Hosama, e Nedabias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 3, 19, 'E os filhos de Pedaías foram: Zorobabel, e Simei. E os filhos de Zorobabel foram: Mesulão, Hananias, e sua irmã Selomite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 3, 20, 'E os cinco outros: Hasubá, Oel, Berequias, Hasadias, e Jusabe-Hesede.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 3, 21, 'Os filhos de Hananias: Pelatias, e Jesaías, os filhos de Refaías, os filhos de Arnã, os filhos de Obadias, e os filhos de Secanias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 3, 22, 'E o filho de Secanias foi Semaías; e os filhos de Samaías foram seis: Hatus, Igal, Bariá, Nearias, e Safate.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 3, 23, 'E os filhos de Nearias foram três: Elioenai, Ezequias, e Azricão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 3, 24, 'Os filhos de Elioenai foram sete: Hodavias, Eliasibe, Pelaías, Acube, Joanã, Delaías, e Anani.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 1, 'Os filhos de Judá foram: Perez, Hezrom, Carmi, Hur, e Sobal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 2, 'E Reaías, filho de Sobal, gerou a Jaate; e Jaate gerou a Aumai e a Laade. Estas são as famílias dos Zoratitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 3, 'E estas são as do pai de Etã: Jezreel, Isma, e Idbás. E o nome da irmã deles era Hazelelponi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 4, 'E Penuel foi pai de Gedor, e Ézer pai de Husá. Estes foram os filhos de Hur, primogênito de Efrata, pai de Belém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 5, 'E Asur, pai de Tecoa, teve duas mulheres: Helá, e Naará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 6, 'E Naará lhe gerou a Auzão, Héfer, Temeni, e a Haastari. Estes foram os filhos de Naará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 7, 'E os filhos de Helá foram: Zerete, Zoar, e Etnã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 8, 'E Coz gerou a Anube, e a Zobeba, e as famílias de Aarel, filho de Harum.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 9, 'E Jabez foi mais honrado que seus irmãos; sua mãe o chamara de Jabez, dizendo: Pois com dores eu o dei à luz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 10, 'Mas Jabez invocou ao Deus de Israel, dizendo: Ah, se tu me abençoares muito, e ampliares os meus limites, e se tua mão for comigo, e me protegeres do mal, para que eu não sofra! E Deus fez suceder o que ele havia pedido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 11, 'E Quelube, irmão de Suá gerou a Maquir, que foi o pai de Estom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 12, 'E Estom gerou a Bete-Rafa, Paseia, e a Teína, pai da cidade de Naás; estes foram os homens de Reca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 13, 'Os filhos de Quenaz foram: Otniel e Seraías. Os filhos de Otniel: Hatate [e Meonotai] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 14, 'E Meonotai gerou a Ofra; e Seraías gerou a Joabe, pai [dos moradores] do Vale dos Artesãos, porque foram artesãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 15, 'Os filhos de Calebe, filho de Jefoné foram: Iru, Elá, e Naã; e filho de Elá foi Quenaz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 16, 'Os filhos de Jealelel foram: Zife, Zifa, Tíria, e Asareel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 17, 'E os filhos de Ezra foram: Jéter, Merede, Efer, e Jalom. E [sua mulher] também deu à luz a Miriã, Samai, e a Isbá, pai de Estemoa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 18, 'E sua mulher Judia lhe deu à luz a Jerede pai de Gedor, a Héber pai de Socó, e a Jecutiel pai de Zanoa. Estes foram os filhos de Bitias, filha de Faraó, a qual Merede teve por esposa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 19, 'E os filhos da mulher de Hodias, irmã de Naã, foram: o pai de Queila o garmita, e Estemoa o maacatita.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 20, 'E os filhos de Simeão foram: Amnom, Rina, Ben-Hanã, e Tilom. E os filhos de Isi foram: Zoete, e Ben-Zoete.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 21, 'Os filhos de Selá, filho de Judá foram: Er, pai de Leca, e Lada, pai de Maressa, e as famílias da casa dos [trabalhadores] do linho em Bete-Asbeia;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 22, 'Como também Joquim, os homens de Cozeba, Joás, e Sarafe (os quais dominaram sobre os moabitas), e Jasubi-Leem. Estes registros, porém, são antigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 23, 'Estes foram oleiros, e habitavam em Netaim e Gedera; eles ficaram ali com o rei em sua obra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 24, 'Os filhos de Simeão foram: Nemuel, Jamim, Jaribe, Zerá, Saul;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 25, 'Cujo filho foi Salum, cujo filho foi Mibsão, cujo filho foi e Misma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 26, 'Os filhos de Misma foram: seu filho Hamuel, cujo filho foi Zacur, cujo filho foi Simei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 27, 'E Simei teve dezesseis filhos e seis filhas, porém seus irmãos não tiveram muitos filhos, e toda a sua família não se multiplicou tanto como a dos filhos de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 28, 'E habitaram em Berseba, Moladá, Hazar-Sual,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 29, 'E em Bila, Ezém, Tolade,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 30, 'Betuel, Hormá, Ziclague.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 31, 'Bete-Marcabote, Hazar-Susim, Bete-Birai, e em Saaraim. Estas foram suas cidades até quando Davi começou a reinar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 32, 'E suas aldeias foram: Etã, Aim, Rimom, e Toquém, e Asã, cinco cidades;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 33, 'E todas as suas aldeias que estavam ao redor destas cidades, até Baal. Estas foram suas habitações, e suas genealogias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 34, 'Porém Mesobabe, Janleque, Josias filho de Amazias;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 35, 'Joel, Jeú filho de Josibias, filho de Seraías, filho de Asiel;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 36, 'E Elioenai, Jaacobá, Jesoaías, Asaias, Adiel, Jesimiel, Benaia;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 37, 'E Ziza filho de Sifi, filho de Alom, filho de Jedaías, filho de Sinri, filho de Semaías.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 38, 'Estes registrados por [seus] nomes foram os líderes de suas famílias, e que foram multiplicados muito nas casas de seus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 39, 'E chegaram até a entrada de Gedor, até o oriente do vale, buscando pastos para suas ovelhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 40, 'E acharam pastos férteis e bons, e a terra era espaçosa, quieta, e descansada, porque os de Cam tinham habitado ali antes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 41, 'Estes, pois, que foram escritos por seus nomes, vieram nos dias de Ezequias rei de Judá, e derrubaram as tendas e habitações dos que se acharam ali, e os destruíram até hoje; e habitaram ali em seu lugar, porque ali havia pastos para suas ovelhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 42, 'Também [alguns] deles, quinhentos homens dos filhos de Simeão, se foram ao monte de Seir, levando como capitães a Pelatias, Nearias, Refaías, e a Uziel, filhos de Isi;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 4, 43, 'E mataram os que haviam restado dos amalequitas, e habitaram ali até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 5, 1, 'Quanto aos filhos de Rúben, primogênito de Israel (porque ele era o primogênito, mas como profanou a cama de de seu pai, seu direito de primogenitura foi dado aos filhos de José, filho de Israel; e não foi contado por primogênito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 5, 2, 'Pois Judá foi o mais poderoso sobre seus irmãos, e o líder veio dele; mas o direito de primogenitura pertenceu a José).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 5, 3, 'Os filhos de Rúben, primogênito de Israel, foram, pois: Enoque, Palu, Hezrom e Carmi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 5, 4, 'Os filhos de Joel foram: seu filho Semaías, seu filho Gogue, seu filho Simei;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 5, 5, 'Seu filho Mica, seu filho Reaías, seu filho Baal;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 5, 6, 'Seu filho Beera, o qual foi transportado por Tiglate-Pilneser, rei dos Assírios. Este era um líder dos Rubenitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 5, 7, 'E seus irmãos por suas famílias, quando foram registrados em suas descendências, tinham por líderes a Jeiel, Zacarias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 5, 8, 'E Belá, filho de Azaz, filho de Sema, filho de Joel. Eles habitaram em Aroer até Nebo e Baal-Meom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 5, 9, 'Habitaram também desde o oriente até a entrada do deserto desde o rio Eufrates; porque seu gado tinha se multiplicado na terra de Gileade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 5, 10, 'E nos dias de Saul fizeram guerra contra os hagarenos, que caíram em suas mãos; e eles habitaram em suas tendas sobre toda a região oriental de Gileade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 5, 11, 'E os filhos de Gade habitaram na vizinhança deles na terra de Basã até Salca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 5, 12, 'E Joel foi o líder em Basã, o segundo Safã, em seguida Janai, e Safate.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 5, 13, 'E seus irmãos, segundo as famílias de seus pais, foram sete: Micael, Mesulão, Sebá, Jorai, Jacã, Zia, e Héber.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 5, 14, 'Estes foram os filhos de Abiail filho de Huri, filho de Jaroa, filho de Gileade, filho de Micael, filho de Jesisai, filho de Jado, filho de Buz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 5, 15, 'Aí, filho de Abdiel, filho de Guni, foi chefe da casa de seus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 5, 16, 'Eles habitaram em Gileade, em Basã, e em suas aldeias, e em todos os campos de Sarom até os seus extremos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 5, 17, 'Todos estes foram contados segundo suas genealogias nos dias de Jotão, rei de Judá, e no dias de Jeroboão, rei de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 5, 18, 'Os filhos de Rúben, e de Gade, e da meia tribo de Manassés, homens guerreiros, homens que traziam escudo e espada, que entesavam arco, e habilidosos em guerra, havia quarenta e quatro mil setecentos e sessenta capazes de ir para a batalha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 5, 19, 'E fizeram guerra contra os Hagarenos, como também a Jetur, Nafis, e Nodabe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 5, 20, 'E foram ajudados contra ele; assim os hagarenos, e todos quantos estavam com eles, foram enregues em suas mãos, porque clamaram a Deus na batalha, e ele lhes atendeu, pois confiaram nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 5, 21, 'E tomaram seu gado, cinquenta mil de seus camelos, duzentas e cinquenta mil ovelhas, dois mil asnos, e cem mil pessoas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 5, 22, 'E muitos caíram mortos, porque a guerra era de Deus; e habitaram em seus lugares até o cativeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 5, 23, 'E os filhos da meia tribo de Manassés habitaram naquela terra, e eles se multiplicaram desde Basã até Baal-Hermom, e Senir e o monte de Hermom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 5, 24, 'E estes foram os cabeças das casas de seus pais: Efer, Isi, Eliel, Azriel, Jeremias, Hodavias, e Jadiel, homens valentes e fortes, homens renomados, e cabeças das casas de seus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 5, 25, 'Porém eles transgrediram contra o Deus de seus pais, e se prostituíram seguindo os deuses dos povos da terra, aos quais o SENHOR havia destruído de diante deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 5, 26, 'Por isso o Deus de Israel despertou ao espírito de Pul, rei da Assíria, e ao espírito de Tiglate-Pilneser, rei da Assíria, o qual levou presos os rubenitas, os gaditas e à meia tribo de Manassés, e os trouxe até Hala, Habor, Hara, e ao rio Gozã, até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 1, 'Os filhos de Levi foram: Gérson, Coate, e Merari.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 2, 'Os filhos de Coate: Anrão, Izar, Hebrom e Uziel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 3, 'Os filhos de Anrão: Arão, Moisés, e Miriã. E os filhos de Arão foram: Nadabe, Abiú, Eleazar, e Itamar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 4, 'E Eleazar gerou a Fineias, Fineias gerou a Abisua;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 5, 'Abisua gerou a Buqui, Buqui gerou a Uzi;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 6, 'Uzi gerou a Zeraías, Zeraías gerou a Meraiote;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 7, 'Meraiote gerou a Amarias, Amarias gerou a Aitube;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 8, 'Aitube gerou a Zadoque, Zadoque gerou a Aimaaz;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 9, 'Aimaaz gerou a Azarias, Azarias gerou a Joanã;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 10, 'Joanã gerou a Azarias (este é o que administrou o sacerdócio na casa que Salomão edificou em Jerusalém);'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 11, 'Azarias gerou a Amarias, Amarias gerou a Aitube;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 12, 'Aitube gerou a Zadoque, Zadoque gerou a Salum;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 13, 'Salum gerou a Hilquias, Hilquias gerou a Azarias;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 14, 'Azarias gerou a Seraías, Seraías, gerou a Jeozadaque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 15, 'E Jeozadaque foi [levado cativo] quando O SENHOR levou Judá e a Jerusalém como prisioneiros, pela mão de Nabucodonosor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 16, 'Os filhos de Levi foram: Gérson, Coate, e Merari.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 17, 'E estes são os nomes dos filhos de Gérson: Libni, e Simei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 18, 'Os filhos de Coate: Anrão, Izar, Hebrom, e Uziel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 19, 'Os filhos de Merari: Mali, e Musi. Estas são as famílias de Levi, segundo seus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 20, 'De Gérson: seu filho Libni, seu filho Jaate, seu filho Zima.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 21, 'Seu filho Joabe, seu filho Ido, seu filho Zerá, e seu filho Jeaterai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 22, 'Os filhos de Coate foram: seu filho Aminadabe, seu filho Corá, seu filho Assir,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 23, 'Seu filho Elcana, seu filho Ebiasafe, seu filho Assir,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 24, 'Seu filho Taate, seu filho Uriel, seu filho Uzias, e seu filho Saul.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 25, 'E os filhos Elcana foram: Amasai e Aimote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 26, '[Quanto] a Elcana, os filhos de Elcana foram: seu filho Zofai, seu filho Naate,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 27, 'Seu filho Eliabe, seu filho Jeroão, e seu filho Elcana.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 28, 'E os filhos de Samuel foram: o primogênito Vasni, e Abias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 29, 'Os filhos de Merari: Mali, seu filho Libni, seu filho Simei, seu filho Uzá,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 30, 'Seu filho Simeia, seu filho Hagias, e seu filho Asaías.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 31, 'Estes, pois, são os que Davi constituiu para o ofício da música da casa do Senhor, depois que a arca teve repouso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 32, 'E eles serviam diante da tenda do tabernáculo da congregação com cânticos, até que Salomão edificou a casa do SENHOR em Jerusalém; e estiveram segundo seu costume em seu serviço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 33, 'Estes, pois, foram os que ali estavam com seus filhos: dos filhos dos coatitas, Hemã, o cantor, filho de Joel, filho de Samuel,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 34, 'Filho de Elcana, filho de Jeroão, filho de Eliel, filho de Toá,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 35, 'Filho de Zufe, filho de Elcana, filho Maate, filho de Amasai,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 36, 'Filho de Elcana, filho de Joel, filho de Azarias, filho de Sofonias,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 37, 'Filho de Taate, filho de Assir, filho de Ebiasafe, filho de Corá,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 38, 'Filho de Izar, filho de Coate, filho de Levi, filho de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 39, 'E seu irmão Asafe estava à sua direita; Asafe era, filho de Berequias, filho de Simeia,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 40, 'Filho de Micael, filho de Baaseias, filho de Malquias,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 41, 'Filho de Etni, filho de Zerá, filho de Adaías,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 42, 'Filho de Etã, filho de Zima, filho de Simei;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 43, 'Filho de Jaate, filho de Gérson, filho de Levi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 44, 'E seus irmãos, os filhos de Merari, estavam à esquerda; [eram eles] : Etã, filho de Quisi, filho de Abdi, filho de Maluque,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 6, 45, 'Filho de Hasabias, filho de Amazias, filho de Hilquias,')
